2330	+  Stream<bool> get biometricEnabledStream {
2331	+    return Stream<bool>.multi((controller) {
2332	+      controller.add(_value);
2333	+      final subscription = _controller.stream.listen(
2334	+        controller.add,
2335	+        onError: controller.addError,
2336	+        onDone: controller.close,
2337	+      );
2338	+      controller.onCancel = subscription.cancel;
2339	+    }, isBroadcast: true);
